package com.rhymeai.app.util

import java.io.InputStream

/**
 * Frequency-rank lookup for English words, backed by the asset generated by
 * scripts/generate-word-frequency.py (shared/pronunciation/word-frequency.txt).
 *
 * The file is one lowercase word per line, ordered most→least frequent.
 * Lines starting with '#' are skipped (header comments).
 *
 * Rank 1 = most frequent; words absent from the list return Int.MAX_VALUE so
 * they sort to the end rather than being dropped.
 *
 * The process-wide singleton is [WordFrequency.shared]. Call
 * [WordFrequency.shared.initialize] at startup. A not-yet-initialised or
 * failed-to-load instance returns MAX_VALUE for every query so the rest of
 * the system degrades gracefully (frequency ordering is skipped, not broken).
 *
 * A separate instance can be constructed and loaded via [load] for tests.
 *
 * Setup for tests:
 *   val wf = WordFrequency()
 *   wf.load(sequenceOf("the", "to", "and"))
 */
class WordFrequency {

    companion object {
        /** The process-wide singleton. Call [initialize] at app startup. */
        val shared = WordFrequency()

        /** Sentinel rank for words not present in the frequency list. */
        const val UNKNOWN_RANK = Int.MAX_VALUE
    }

    @Volatile private var rankMap: Map<String, Int> = emptyMap()

    val isLoaded: Boolean get() = rankMap.isNotEmpty()

    /**
     * Load from an asset InputStream. Idempotent: a second call replaces the map.
     * Use at startup: [shared.initialize(assets.open("word-frequency.txt"))].
     */
    fun initialize(inputStream: InputStream) {
        load(inputStream.bufferedReader().lineSequence())
    }

    /**
     * Load from any line sequence (useful in tests without an Android context).
     * Lines starting with '#' and blank lines are skipped.
     */
    fun load(lines: Sequence<String>) {
        val map = HashMap<String, Int>(32_768)
        var rank = 1
        for (line in lines) {
            if (line.isBlank() || line.startsWith('#')) continue
            val word = line.trim().lowercase()
            if (word.isNotEmpty()) {
                map[word] = rank++
            }
        }
        rankMap = map
    }

    /** Returns the frequency rank (1 = most common) or UNKNOWN_RANK if absent. */
    fun rankOf(word: String): Int = rankMap[word.lowercase()] ?: UNKNOWN_RANK

    /**
     * Stably re-sort a list of words by frequency rank (common first).
     * If the list is not loaded, returns [words] unchanged.
     */
    fun sortByFrequency(words: List<String>): List<String> {
        if (rankMap.isEmpty()) return words          // not loaded — preserve input order
        return words.sortedBy { rankOf(it) }
    }
}
